'use strict';
let D, rows=[], chosen=[];const $=id=>document.getElementById(id),fmt=n=>Number(n).toLocaleString('pt-BR'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),pretty=s=>s==='NAO_INFORMADO'?'Não informado':String(s).toLocaleLowerCase('pt-BR').replace(/(^|\s)\S/g,c=>c.toUpperCase()),sum=(arr,k)=>arr.reduce((s,r)=>s+(r[k]||0),0);
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab],.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.tab).classList.add('active')}));
function options(id,vals){if(id==='weather'&&vals.every(x=>x==='NAO_INFORMADO')){$(id).disabled=true;$(id).options[0].text='Não informada na base de RO';$('weatherNote').hidden=false;return}for(const v of [...new Set(vals)].sort()){const o=document.createElement('option');o.value=v;o.textContent=pretty(v);$(id).append(o)}}
function group(rs,key,metric='n'){const m={};for(const r of rs){const k=r[key]||'NAO_INFORMADO';m[k]=(m[k]||0)+r[metric]}return m}
function bars(id,obj,limit=10){const a=Object.entries(obj).sort((a,b)=>b[1]-a[1]).slice(0,limit),max=Math.max(...a.map(x=>x[1]),1),total=Object.values(obj).reduce((a,b)=>a+b,0);$(id).innerHTML=a.length?a.map(([k,v])=>`<div class="barrow"><div class="barlabel"><span>${esc(pretty(k))}</span><b>${fmt(v)} <span style="font-weight:400;color:#a39d7c"> · ${total?(v/total*100).toFixed(1).replace('.',','):0}%</span></b></div><div class="bartrack"><div class="barfill" style="width:${v/max*100}%"></div></div></div>`).join(''):'<p class="empty">Nenhum registro nesta seleção.</p>'}
function plot(id,items,{unit='',color='#facc15',bar=false}={}){const el=$(id),valid=items.filter(x=>x[1]!==null);if(!valid.length){el.innerHTML='<p class="empty">Sem observações válidas nesta seleção.</p>';return}const W=680,H=240,L=48,R=14,T=16,B=38,w=W-L-R,h=H-T-B,max=Math.max(...valid.map(x=>x[1]),1)*1.12,x=i=>L+(items.length<2?w/2:i*w/(items.length-1)),y=v=>T+h-v/max*h;let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(el.parentElement.querySelector('h2').textContent)}"><title>${items.map(([k,v])=>esc(k)+': '+(v===null?'sem dados':fmt(v))+unit).join('; ')}</title>`;for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#393722" stroke-dasharray="3 4"/><text x="${L-10}" y="${y(v)+3}" text-anchor="end" font-size="9" fill="#aaa58f">${fmt(Math.round(v))}</text>`}if(bar){const bw=Math.min(34,w/items.length*.65);items.forEach(([k,v],i)=>{if(v!==null)svg+=`<rect x="${x(i)-bw/2}" y="${y(v)}" width="${bw}" height="${T+h-y(v)}" rx="3" fill="${color}"><title>${esc(k)}: ${fmt(v)} ${unit}</title></rect>`})}else{let seg=[];const flush=()=>{if(!seg.length)return;svg+=`<path d="M${seg[0][0]},${T+h} L${seg.map(p=>p.join(',')).join(' L')} L${seg.at(-1)[0]},${T+h} Z" fill="#3a310c"/><path d="M${seg.map(p=>p.join(',')).join(' L')}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linejoin="round"/>`;seg=[]};items.forEach(([k,v],i)=>{if(v===null)flush();else seg.push([x(i),y(v)])});flush();items.forEach(([k,v],i)=>{if(v!==null)svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="${color}"><title>${esc(k)}: ${fmt(v)} ${unit}</title></circle>`})}const step=Math.max(1,Math.ceil(items.length/8));items.forEach(([k,v],i)=>{if(i%step===0||i===items.length-1)svg+=`<text x="${x(i)}" y="${H-13}" text-anchor="middle" font-size="9" fill="#aaa58f">${esc(k)}</text>`});el.innerHTML=svg+'</svg>'}
function dimensions(field){const result={};for(const r of D.dimensions){if(r.field!==field||($('year').value&&!r.month.startsWith($('year').value))||($('city').value&&r.city!==$('city').value))continue;for(const [k,v] of Object.entries(r.values))result[k]=(result[k]||0)+v}return result}
function render(){const year=$('year').value,city=$('city').value,weather=$('weather').value;chosen=rows.filter(r=>(!year||r.date.startsWith(year))&&(!city||r.city===city)&&(!weather||r.weather===weather));const total=sum(chosen,'n'),deaths=sum(chosen,'deaths'),people=sum(chosen,'involved'),fatal=sum(chosen,'fatal');$('kpis').innerHTML=[['Acidentes registrados',fmt(total),'Soma dos acidentes da base','↗'],['Pessoas envolvidas',fmt(people),'Todas as gravidades registradas','◎'],['Óbitos registrados',fmt(deaths),`${fmt(fatal)} acidentes com óbito`,'+'],['Óbitos por 100 acidentes',total?(deaths/total*100).toFixed(2).replace('.',','):'—','Razão descritiva do recorte','%']].map(([l,v,s,icon])=>`<article class="kpi"><span class="label">${l}</span><span class="symbol">${icon}</span><strong>${v}</strong><small>${s}</small></article>`).join('');
const monthly={};for(const r of chosen){const m=r.date.slice(0,7);monthly[m]=(monthly[m]||0)+r.n}const start=year?`${year}-01`:D.period[0].slice(0,7),end=year?`${year}-12`:D.period[1].slice(0,7),series=[];let cursor=start;while(cursor<=end){const [y,m]=cursor.split('-').map(Number);const within=cursor>=D.period[0].slice(0,7)&&cursor<=D.period[1].slice(0,7);series.push([cursor.slice(5)+'/'+cursor.slice(2,4),within?(monthly[cursor]||0):null]);cursor=m===12?`${y+1}-01`:`${y}-${String(m+1).padStart(2,'0')}`}plot('trend',series);$('periodnote').textContent=`Cobertura recebida: ${D.period[0]} a ${D.period[1]}. Meses fora da cobertura não são convertidos em zero. Último ano pode ser parcial.`;bars('types',group(chosen,'type'),7);bars('cities',group(chosen,'city'),10);
const week=group(chosen,'weekday'),order=['SEGUNDA-FEIRA','TERCA-FEIRA','QUARTA-FEIRA','QUINTA-FEIRA','SEXTA-FEIRA','SABADO','DOMINGO'];$('week').innerHTML=order.map(k=>`<div class="barrow"><div class="barlabel"><span>${pretty(k)}</span><b>${fmt(week[k]||0)}</b></div><div class="bartrack"><div class="barfill" style="width:${(week[k]||0)/Math.max(...Object.values(week),1)*100}%"></div></div></div>`).join('');$('phases').innerHTML=Object.entries(group(chosen,'phase')).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="phase">${esc(pretty(k))}<b>${fmt(v)}</b></div>`).join('');for(const [id,f] of [['ages','faixa_idade'],['injury','gravidade_lesao'],['gender','genero'],['vehicles','tipo_veiculo'],['roles','tp_envolvido']])bars(id,dimensions(f),30);renderClimate()}
function renderClimate(){const st=$('station').value,rs=D.climate.filter(r=>!st||r.code===st),months=Array.from({length:12},(_,i)=>'2023-'+String(i+1).padStart(2,'0')),rain=[],temp=[];for(const m of months){const a=rs.filter(r=>r.month===m),p=a.filter(r=>r.rain!==null),t=a.filter(r=>r.temp!==null),hours=sum(t,'tempHours');rain.push([m.slice(5)+'/23',p.length?Math.round(sum(p,'rain')/p.length*10)/10:null]);temp.push([m.slice(5)+'/23',hours?Math.round(t.reduce((s,r)=>s+r.temp*r.tempHours,0)/hours*10)/10:null])}plot('rain',rain,{unit:'mm',bar:true,color:'#facc15'});plot('temp',temp,{unit:'°C',color:'#f59e0b'});const ss={};for(const r of rs){if(!ss[r.code])ss[r.code]={name:r.station,hours:0,valid:0};ss[r.code].hours+=r.hours;ss[r.code].valid+=r.rainHours}$('stations').innerHTML=Object.entries(ss).map(([k,s])=>`<tr><td>${esc(pretty(s.name))}</td><td>${esc(k)}</td><td>${fmt(s.hours)}</td><td>${fmt(s.valid)}</td><td>${(s.valid/8760*100).toFixed(1).replace('.',',')}%</td></tr>`).join('')}
function quality(){const a=D.audit.sources,total=a.reduce((s,r)=>s+r.read,0),duplicates=a.reduce((s,r)=>s+r.duplicatesOrOlder,0),rejected=a.reduce((s,r)=>s+r.malformed+r.missingKey,0);$('qualitystats').innerHTML=[['Linhas nacionais lidas',fmt(total)],['Chaves de acidentes no Brasil',fmt(D.audit.counts.acidentes)],['Linhas repetidas ou antigas ignoradas',fmt(duplicates)],['Linhas rejeitadas',fmt(rejected)],['Veiculos sem acidente (quarentena)',fmt(D.audit.quarantineCounts?.veiculos_sem_acidente||0)],['Estações INMET no Brasil',fmt(D.climateAudit.length)],['Observações horárias de clima',fmt(sum(D.climateAudit,'rows'))],['Acidentes RO sem coordenadas',fmt(D.quality.coordinates||0)],['Acidentes RO sem localidade',fmt(D.quality.locality||0)],['Período dos acidentes',D.period.join(' → ')]].map(([k,v])=>`<div class="qualityrow"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('');$('audit').innerHTML=a.map(r=>`<tr><td>${pretty(r.table)}</td><td>${esc(r.archive)}${r.identicalArchives.length?`<br><small>Idênticos: ${esc(r.identicalArchives.join(', '))}</small>`:''}</td><td>${fmt(r.read)}</td><td>${fmt(r.retainedNewKeys)}</td><td>${fmt(r.duplicatesOrOlder)}</td><td>${fmt(r.malformed+r.missingKey)}</td></tr>`).join('');$('sourcefooter').textContent=`Fontes: bases fornecidas + INMET · Tratamento em ${new Date(D.generated).toLocaleDateString('pt-BR')}`}
['year','city','weather'].forEach(id=>$(id).addEventListener('change',render));$('station').addEventListener('change',renderClimate);$('reset').addEventListener('click',()=>{['year','city','weather'].forEach(id=>$(id).value='');render()});$('download').addEventListener('click',()=>{const f=D.fields,headers=['data_acidente','municipio','tipo_acidente','condicao_meteorologica','fase_dia','dia_semana','hora','condicao_pista','quantidade_acidentes','obitos','envolvidos','feridos_ou_ilesos','acidentes_com_obito','registros_de_origem'],csv='\ufeff'+[headers,...chosen.map(r=>f.map(k=>r[k]))].map(a=>a.map(s=>'"'+String(s??'NAO_INFORMADO').replaceAll('"','""')+'"').join(';')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='ro-selecao-tratada.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});
(async()=>{try{const response=await fetch('data.json.gz');if(!response.ok)throw Error('HTTP '+response.status);const stream=response.body.pipeThrough(new DecompressionStream('gzip'));D=await new Response(stream).json();rows=D.records.map(a=>Object.fromEntries(D.fields.map((f,i)=>[f,a[i]])));options('year',rows.map(r=>r.date.slice(0,4)));options('city',rows.map(r=>r.city));options('weather',rows.map(r=>r.weather));for(const [code,name] of new Map(D.climate.map(r=>[r.code,r.station]))){const o=document.createElement('option');o.value=code;o.textContent=pretty(name);$('station').append(o)}quality();render();$('status').hidden=true;$('app').hidden=false;window.dashboardReady=true}catch(e){$('status').textContent='Não foi possível carregar os dados. Recarregue a página para tentar novamente.';console.error(e)}})();
